import { describe, it, expect } from "vitest";
import { attachFlyControls } from "./fly-controls";

function makeCanvas() {
    const listeners = new Map<string, Set<(e: any) => void>>();
    const canvas: any = {
        tabIndex: -1,
        hasAttribute: () => false,
        addEventListener: (t: string, f: any) => { if (!listeners.has(t)) listeners.set(t, new Set()); listeners.get(t)!.add(f); },
        removeEventListener: (t: string, f: any) => { listeners.get(t)?.delete(f); },
        setPointerCapture() {}, releasePointerCapture() {},
        fire: (t: string, e: any) => { for (const f of [...(listeners.get(t) ?? [])]) f(e); },
        count: () => [...listeners.values()].reduce((n, s) => n + s.size, 0),
    };
    return canvas;
}
function makeCamera() {
    const position = { x: 0, y: 0, z: 0 };
    const target = { x: 0, y: 0, z: 1, set(x: number, y: number, z: number) { this.x = x; this.y = y; this.z = z; } };
    return { position, target, speed: 1, inertia: 0.9, angularSensitivity: 1000, _yaw: 0, _pitch: 0 } as any;
}
function run(keysDown: string[], frames: number) {
    const canvas = makeCanvas();
    const camera = makeCamera();
    const scene: any = { _beforeRender: [] as any[] };
    const dispose = attachFlyControls(camera, canvas, scene);
    for (const k of keysDown) canvas.fire("keydown", { code: k });
    for (let i = 0; i < frames; i++) for (const h of [...scene._beforeRender]) h(16);
    return { camera, canvas, scene, dispose };
}
describe("attachFlyControls", () => {
    it("Shift alone never moves vertically", () => {
        for (const sh of ["ShiftLeft", "ShiftRight"]) {
            const r = run([sh], 60);
            expect(r.camera.position.y).toBe(0);
            r.dispose();
        }
    });
    it("Shift with W does not move vertically", () => {
        const r = run(["ShiftLeft", "KeyW"], 60);
        expect(Math.abs(r.camera.position.y)).toBeLessThan(1e-9);
        expect(Math.hypot(r.camera.position.x, r.camera.position.z)).toBeGreaterThan(0);
        r.dispose();
    });
    it("Shift multiplies speed by 3", () => {
        const a = run(["KeyW"], 1);
        const b = run(["KeyW", "ShiftRight"], 1);
        expect(b.camera.position.z / a.camera.position.z).toBeCloseTo(3, 6);
        a.dispose(); b.dispose();
    });
    it("Space rises, PageDown sinks", () => {
        const up = run(["Space"], 10); expect(up.camera.position.y).toBeGreaterThan(0); up.dispose();
        const down = run(["PageDown"], 10); expect(down.camera.position.y).toBeLessThan(0); down.dispose();
    });
    it("dispose removes listeners and the frame hook", () => {
        const r = run(["KeyW"], 2);
        expect(r.scene._beforeRender.length).toBe(1);
        r.dispose();
        expect(r.scene._beforeRender.length).toBe(0);
        expect(r.canvas.count()).toBe(0);
    });
});
